(function(){document.addEventListener("DOMContentLoaded",()=>{document.querySelectorAll('script[id^="product-badge-variant-data-"]').forEach(a=>{const i=a.id.slice(27),e=document.getElementById(`badge-container-${i}`);if(!e||e.dataset.badgeBound==="true")return;e.dataset.badgeBound="true";let n={variants:[]};try{n=JSON.parse(a.textContent)}catch(t){console.error("Failed to parse stock badge data",t)}function r(t){const d=n.variants.find(o=>o.id===parseInt(t));d&&(d.available?e.style.display="":e.style.display="none")}document.addEventListener("variant-changed",t=>{t.detail&&t.detail.variantId&&r(t.detail.variantId)})})})})();
